import {STM32_BOARDS} from './stm32-boards.js';
import {crc32} from './project-zip.js';
const HEADER=80;
export function packSTMImage(bytes,board){if(!STM32_BOARDS[board])throw Error('STM32 hedefi geçersiz.');const image=new Uint8Array(HEADER+bytes.length),v=new DataView(image.buffer);image.set(new TextEncoder().encode('CFSTM01\0'));image.set(new TextEncoder().encode(board),8);v.setUint32(64,bytes.length,true);v.setUint32(68,crc32(bytes),true);image.set(bytes,HEADER);validateSTMImage(image,board);return image;}
export function validateSTMImage(image,board){const b=STM32_BOARDS[board];if(!b||!(image instanceof Uint8Array)||image.length<HEADER+8)throw Error('STM32 firmware başlığı geçersiz.');const v=new DataView(image.buffer,image.byteOffset,image.byteLength),magic=new TextDecoder().decode(image.subarray(0,8)),id=new TextDecoder().decode(image.subarray(8,64)).replace(/\0.*$/s,'');const bytes=image.subarray(HEADER);if(image.subarray(72,80).some(v=>v!==0)||magic!=='CFSTM01\0'||id!==board||v.getUint32(64,true)!==bytes.length||bytes.length>b.flashSize||crc32(bytes)!==v.getUint32(68,true))throw Error('STM32 firmware hedefi/boyutu/checksum geçersiz.');const sp=v.getUint32(HEADER,true),reset=v.getUint32(HEADER+4,true);if(sp!==0x20000000+b.ram||!(reset&1)||reset<0x08000000||reset>=0x08000000+bytes.length)throw Error('STM32 reset vektörü geçersiz.');return bytes;}
